# React + TypeScript + Vite

This template provides a minimal setup to get React working in Vite with HMR and some ESLint rules.

Currently, two official plugins are available:

- [@vitejs/plugin-react](https://github.com/vitejs/vite-plugin-react/blob/main/packages/plugin-react) uses [Babel](https://babeljs.io/) (or [oxc](https://oxc.rs) when used in [rolldown-vite](https://vite.dev/guide/rolldown)) for Fast Refresh
- [@vitejs/plugin-react-swc](https://github.com/vitejs/vite-plugin-react/blob/main/packages/plugin-react-swc) uses [SWC](https://swc.rs/) for Fast Refresh

## React Compiler

The React Compiler is not enabled on this template because of its impact on dev & build performances. To add it, see [this documentation](https://react.dev/learn/react-compiler/installation).

## Expanding the ESLint configuration

If you are developing a production application, we recommend updating the configuration to enable type-aware lint rules:

```js
export default defineConfig([
  globalIgnores(['dist']),
  {
    files: ['**/*.{ts,tsx}'],
    extends: [
      // Other configs...

      // Remove tseslint.configs.recommended and replace with this
      tseslint.configs.recommendedTypeChecked,
      // Alternatively, use this for stricter rules
      tseslint.configs.strictTypeChecked,
      // Optionally, add this for stylistic rules
      tseslint.configs.stylisticTypeChecked,

      // Other configs...
    ],
    languageOptions: {
      parserOptions: {
        project: ['./tsconfig.node.json', './tsconfig.app.json'],
        tsconfigRootDir: import.meta.dirname,
      },
      // other options...
    },
  },
])
```

You can also install [eslint-plugin-react-x](https://github.com/Rel1cx/eslint-react/tree/main/packages/plugins/eslint-plugin-react-x) and [eslint-plugin-react-dom](https://github.com/Rel1cx/eslint-react/tree/main/packages/plugins/eslint-plugin-react-dom) for React-specific lint rules:

```js
// eslint.config.js
import reactX from 'eslint-plugin-react-x'
import reactDom from 'eslint-plugin-react-dom'

export default defineConfig([
  globalIgnores(['dist']),
  {
    files: ['**/*.{ts,tsx}'],
    extends: [
      // Other configs...
      // Enable lint rules for React
      reactX.configs['recommended-typescript'],
      // Enable lint rules for React DOM
      reactDom.configs.recommended,
    ],
    languageOptions: {
      parserOptions: {
        project: ['./tsconfig.node.json', './tsconfig.app.json'],
        tsconfigRootDir: import.meta.dirname,
      },
      // other options...
    },
  },
])
```

{
  "$schema": "https://ui.shadcn.com/schema.json",
  "style": "new-york",
  "rsc": false,
  "tsx": true,
  "tailwind": {
    "config": "postcss.config.js",
    "css": "src/index.css",
    "baseColor": "slate",
    "cssVariables": true,
    "prefix": ""
  },
  "iconLibrary": "lucide",
  "aliases": {
    "components": "@/components",
    "utils": "@/lib/utils",
    "ui": "@/components/ui",
    "lib": "@/lib",
    "hooks": "@/hooks"
  },
  "registries": {}
}

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@300;400;500;600;700&family=Fraunces:ital,wght@0,700;0,900;1,700&display=swap');

:root {
  --bg: #ffffff;
  --bg-secondary: #f5f5f5;
  --bg-tertiary: #f0f0f0;
  --text: #111111;
  --text-secondary: #707072;
  --text-muted: #9e9e9e;
  --accent: #111111;
  --accent-orange: #fa5400;
  --accent-orange-hover: #e04d00;
  --accent-green: #007d48;
  --border: #e5e5e5;
  --border-light: #f0f0f0;
  --font-body: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  --font-display: 'Fraunces', Georgia, serif;
  --accent-green: #09BA7D;
  --transition: cubic-bezier(0.25, 0.46, 0.45, 0.94);
  --transition-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html {
  scroll-behavior: smooth;
  overflow-x: hidden;
}

body {
  background: #f0f0f0;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 14px;
  line-height: 1.5;
  overflow-x: hidden;
  min-height: 100vh;
  -webkit-overflow-scrolling: touch;
}

::-webkit-scrollbar { width: 0; height: 0; }

/* ========== APP CONTAINER ========== */
.app-container {
  max-width: 480px;
  margin: 0 auto;
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;
  background: var(--bg);
}

/* ========== PAGE TRANSITIONS ========== */
.page {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  background: var(--bg);
  will-change: transform;
}

.page-enter {
  animation: pageEnter 0.35s var(--transition) forwards;
}

.page-exit {
  animation: pageExit 0.35s var(--transition) forwards;
}

@keyframes pageEnter {
  from { transform: translateX(100%); opacity: 0.8; }
  to { transform: translateX(0); opacity: 1; }
}

@keyframes pageExit {
  from { transform: translateX(0); opacity: 1; }
  to { transform: translateX(-30%); opacity: 0.7; }
}

.page-home-enter {
  animation: pageHomeEnter 0.35s var(--transition) forwards;
}

@keyframes pageHomeEnter {
  from { transform: translateX(-30%); opacity: 0.7; }
  to { transform: translateX(0); opacity: 1; }
}

/* ========== HEADER ========== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  transition: all 0.3s var(--transition);
  max-width: 480px;
  margin: 0 auto;
}

.header-scrolled {
  box-shadow: 0 1px 0 rgba(0,0,0,0.05);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  height: 52px;
}

.header-with-back {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header-title {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.3px;
}

.header-btn {
  background: none;
  border: none;
  color: var(--text);
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  position: relative;
  transition: all 0.2s var(--transition);
  border-radius: 50%;
  flex-shrink: 0;
}

.header-btn:active {
  background: var(--bg-secondary);
  transform: scale(0.92);
}

.header-btn svg {
  width: 24px;
  height: 24px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.cart-badge {
  position: absolute;
  top: 2px;
  right: 2px;
  background: var(--accent-orange);
  color: #fff;
  font-family: var(--font-body);
  font-size: 10px;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
}

.logo {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text);
  text-decoration: none;
  line-height: 1;
}

/* ========== FLOATING BOTTOM NAV ========== */
.bottom-nav {
  position: fixed;
  bottom: 18px;
  left: 50%;
  transform: translateX(-50%);
  width: calc(100% - 36px);
  max-width: 440px;
  background: rgba(255,255,255,0.55);
  backdrop-filter: saturate(200%) blur(24px);
  -webkit-backdrop-filter: saturate(200%) blur(24px);
  border: 0.5px solid rgba(255,255,255,0.7);
  border-radius: 26px;
  box-shadow: 0 8px 32px rgba(0,0,0,0.10), 0 1px 4px rgba(0,0,0,0.04);
  z-index: 1000;
  display: flex;
  justify-content: space-around;
  padding: 8px 12px;
}

.bottom-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 4px 16px;
  color: var(--text-muted);
  text-decoration: none;
  transition: all 0.2s;
  cursor: pointer;
  background: none;
  border: none;
  font-family: var(--font-body);
}

.bottom-nav-item.active {
  color: var(--text);
}

.bottom-nav-item svg {
  width: 24px;
  height: 24px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.bottom-nav-item.active svg {
  stroke-width: 2;
}

.bottom-nav-item span {
  font-size: 10px;
  font-weight: 500;
}

.nav-cart-badge {
  position: absolute;
  top: -4px;
  right: -8px;
  background: #fa5400;
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
}

/* ========== DRIP HERO ========== */
.drip-hero {
  position: relative;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.drip-hero-img {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.drip-hero-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
}

.drip-hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    160deg,
    rgba(0,0,0,0.72) 0%,
    rgba(0,0,0,0.45) 50%,
    rgba(0,0,0,0.75) 100%
  );
}

.drip-hero-topbar {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 52px 20px 0;
}

.drip-logo {
  font-family: var(--font-display);
  font-size: 30px;
  font-weight: 900;
  color: #fff;
  letter-spacing: -1.5px;
  line-height: 1;
}

.drip-logo span {
  color: #09BA7D;
}

.drip-hero-actions {
  display: flex;
  gap: 8px;
}

.drip-icon-btn {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  backdrop-filter: blur(10px);
  border: 0.5px solid rgba(255,255,255,0.25);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.2s;
}

.drip-icon-btn:active {
  background: rgba(255,255,255,0.28);
  transform: scale(0.92);
}

.drip-icon-btn svg {
  width: 20px;
  height: 20px;
  stroke: #fff;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.drip-hero-content {
  position: relative;
  z-index: 2;
  margin-top: auto;
  padding: 0 24px 44px;
}

.drip-hero-tag {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: #09BA7D;
  margin-bottom: 14px;
}

.drip-hero-title {
  font-family: var(--font-display);
  font-size: clamp(42px, 13vw, 58px);
  font-weight: 900;
  line-height: 0.93;
  letter-spacing: -2px;
  color: #fff;
  margin-bottom: 14px;
}

.drip-hero-title-accent {
  font-style: italic;
  color: #09BA7D;
}

.drip-hero-sub {
  font-size: 15px;
  font-weight: 400;
  color: rgba(255,255,255,0.65);
  margin-bottom: 28px;
  line-height: 1.5;
  max-width: 300px;
}

.drip-hero-ctas {
  display: flex;
  gap: 12px;
}

.drip-btn-primary {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  padding: 13px 26px;
  border: none;
  border-radius: 30px;
  cursor: pointer;
  background: #09BA7D;
  color: #fff;
  transition: all 0.22s;
  min-height: 46px;
}

.drip-btn-primary:active {
  background: #078a5d;
  transform: scale(0.96);
}

.drip-btn-ghost {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  padding: 13px 26px;
  border: 1.5px solid rgba(255,255,255,0.35);
  border-radius: 30px;
  cursor: pointer;
  background: rgba(255,255,255,0.12);
  backdrop-filter: blur(8px);
  color: #fff;
  transition: all 0.22s;
  min-height: 46px;
}

.drip-btn-ghost:active {
  background: rgba(255,255,255,0.22);
  transform: scale(0.96);
}

/* ========== CATEGORY CARDS ========== */
.drip-cats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  padding: 0 20px;
}

.drip-cat-card {
  border: none;
  border-radius: 16px;
  padding: 16px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  transition: transform 0.18s, box-shadow 0.18s;
  box-shadow: 0 2px 8px rgba(0,0,0,0.05);
}

.drip-cat-card:active {
  transform: scale(0.95);
}

.drip-cat-emoji {
  font-size: 28px;
  line-height: 1;
  margin-bottom: 2px;
}

.drip-cat-label {
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 700;
  color: var(--text);
  text-align: center;
}

.drip-cat-count {
  font-family: var(--font-body);
  font-size: 10px;
  color: var(--text-secondary);
  text-align: center;
}

/* ========== FOOTER LOGO ========== */
.footer-logo {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 900;
  color: var(--text);
  letter-spacing: -1.5px;
  margin-bottom: 24px;
}

.footer-logo span {
  color: #09BA7D;
}

/* ========== HERO ========== */
.hero {
  position: relative;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 0 0 40px;
  overflow: hidden;
  background: var(--bg);
}

.hero-image {
  position: absolute;
  top: 52px;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(180deg, #f5f5f5 0%, #ffffff 60%);
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-image::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 50% at 50% 40%, rgba(250,84,0,0.04) 0%, transparent 70%),
    radial-gradient(ellipse 60% 40% at 30% 60%, rgba(0,0,0,0.02) 0%, transparent 60%);
}

.hero-shoe-watermark {
  font-family: var(--font-display);
  font-size: 140px;
  color: var(--text);
  opacity: 0.04;
  letter-spacing: -4px;
  line-height: 1;
  position: absolute;
  top: 15%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 0;
  pointer-events: none;
}

.hero-visual {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 55vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.hero-visual img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 20px 40px rgba(0,0,0,0.15));
  transform: rotate(-5deg);
  transition: transform 0.6s var(--transition);
}

.hero-content {
  position: relative;
  z-index: 2;
  padding: 0 24px;
}

.hero-label {
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--accent-orange);
  margin-bottom: 12px;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(40px, 12vw, 56px);
  font-weight: 700;
  line-height: 0.95;
  letter-spacing: -1.5px;
  margin-bottom: 16px;
  color: var(--text);
}

.hero-subtitle {
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: 28px;
  line-height: 1.5;
  max-width: 320px;
  opacity: 0;
  animation: fadeIn 0.8s var(--transition) 0.7s forwards;
}

@keyframes fadeIn {
  to { opacity: 1; }
}

.hero-cta {
  display: flex;
  gap: 12px;
  opacity: 0;
  animation: fadeIn 0.8s var(--transition) 0.9s forwards;
}

/* ========== BUTTONS ========== */
.btn {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  padding: 14px 28px;
  border: none;
  border-radius: 30px;
  cursor: pointer;
  transition: all 0.25s var(--transition);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 48px;
  white-space: nowrap;
}

.btn:active {
  transform: scale(0.96);
}

.btn-primary {
  background: var(--text);
  color: #fff;
}

.btn-primary:hover, .btn-primary:active {
  background: #333;
}

.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 1.5px solid var(--border);
}

.btn-secondary:hover, .btn-secondary:active {
  background: var(--bg-secondary);
  border-color: var(--text-secondary);
}

.btn-orange {
  background: var(--accent-orange);
  color: #fff;
}

.btn-orange:hover, .btn-orange:active {
  background: var(--accent-orange-hover);
}

.btn-full {
  width: 100%;
}

/* ========== SECTIONS ========== */
.section {
  padding: 48px 0;
  position: relative;
}

.section-header {
  padding: 0 20px;
  margin-bottom: 20px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
}

.section-label {
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--text-secondary);
  margin-bottom: 4px;
}

.section-title {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.5px;
  color: var(--text);
}

.section-action {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  background: none;
  border: none;
}

/* ========== CATEGORY PILLS ========== */
.category-pills {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding: 0 20px 8px;
  margin-bottom: 20px;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.category-pills::-webkit-scrollbar { display: none; }

.pill {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  padding: 8px 18px;
  border: 1.5px solid var(--border);
  border-radius: 20px;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s var(--transition);
  flex-shrink: 0;
}

.pill.active {
  background: var(--text);
  color: #fff;
  border-color: var(--text);
}

.pill:active {
  transform: scale(0.95);
}

/* ========== PRODUCT CAROUSEL ========== */
.product-carousel {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding: 0 20px 16px;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.product-carousel::-webkit-scrollbar { display: none; }

.product-carousel-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 0 20px;
}

/* ========== PRODUCT CARD ========== */
.product-card {
  flex: 0 0 calc(50% - 6px);
  scroll-snap-align: start;
  cursor: pointer;
  transition: transform 0.2s var(--transition);
}

.product-card-carousel {
  flex: 0 0 200px;
}

.product-card:active {
  transform: scale(0.97);
}

.product-image-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-secondary);
  border-radius: 12px;
  overflow: hidden;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.product-image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s var(--transition);
}

.product-card:hover .product-image-wrap img {
  transform: scale(1.05);
}

.product-tag {
  position: absolute;
  top: 10px;
  left: 10px;
  font-family: var(--font-body);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 4px 10px;
  border-radius: 4px;
  z-index: 2;
}

.product-tag.new {
  background: var(--accent-orange);
  color: #fff;
}

.product-tag.sale {
  background: var(--accent-green);
  color: #fff;
}

.product-wishlist {
  position: absolute;
  top: 10px;
  right: 10px;
  width: 32px;
  height: 32px;
  background: rgba(255,255,255,0.9);
  backdrop-filter: blur(10px);
  border: none;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 2;
  transition: all 0.2s var(--transition);
  box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.product-wishlist:active {
  transform: scale(0.9);
}

.product-wishlist svg {
  width: 16px;
  height: 16px;
  stroke: var(--text);
  fill: none;
  stroke-width: 1.5;
}

.product-wishlist.active svg {
  fill: #ff3b30;
  stroke: #ff3b30;
}

.product-name {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  margin-bottom: 2px;
  line-height: 1.3;
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.product-category {
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 400;
  color: var(--text-secondary);
  margin-bottom: 6px;
}

.product-price {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.product-price .old {
  font-size: 12px;
  text-decoration: line-through;
  color: var(--text-muted);
  margin-left: 6px;
  font-weight: 400;
}

/* ========== FEATURED BANNER ========== */
.featured-banner {
  position: relative;
  margin: 0 20px;
  border-radius: 16px;
  overflow: hidden;
  background: var(--bg-secondary);
  aspect-ratio: 4/5;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 28px;
}

.featured-banner img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(0,0,0,0.6) 100%);
  z-index: 1;
}

.featured-visual {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-display);
  font-size: 120px;
  color: #fff;
  opacity: 0.08;
  line-height: 1;
  z-index: 0;
  pointer-events: none;
}

.featured-content {
  position: relative;
  z-index: 2;
}

.featured-label {
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--accent-orange);
  margin-bottom: 8px;
}

.featured-title {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.5px;
  color: #fff;
  margin-bottom: 12px;
}

.featured-desc {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 400;
  color: rgba(255,255,255,0.8);
  margin-bottom: 20px;
  line-height: 1.5;
}

/* ========== SPORT CATEGORIES ========== */
.sport-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  padding: 0 20px;
}

.sport-card {
  position: relative;
  aspect-ratio: 1;
  background: var(--bg-secondary);
  border-radius: 12px;
  overflow: hidden;
  cursor: pointer;
  transition: all 0.25s var(--transition);
}

.sport-card:active {
  transform: scale(0.96);
}

.sport-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,0.5) 100%);
  z-index: 1;
}

.sport-visual {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 56px;
  color: var(--text);
  opacity: 0.06;
  transition: all 0.3s var(--transition);
}

.sport-card:hover .sport-visual {
  opacity: 0.1;
  transform: scale(1.08);
}

.sport-name {
  position: absolute;
  bottom: 16px;
  left: 16px;
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  color: #fff;
  letter-spacing: -0.3px;
  z-index: 2;
}

/* ========== STORIES ========== */
.story-card {
  flex: 0 0 140px;
  scroll-snap-align: start;
  cursor: pointer;
}

.story-image {
  aspect-ratio: 3/4;
  background: var(--bg-secondary);
  border-radius: 12px;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}

.story-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.story-image::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.3) 100%);
  z-index: 1;
}

.story-visual {
  font-family: var(--font-display);
  font-size: 48px;
  color: var(--text);
  opacity: 0.08;
}

.story-title {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
  line-height: 1.3;
}

.story-subtitle {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--text-secondary);
}

/* ========== MEMBERSHIP STRIP ========== */
.membership-strip {
  background: var(--bg-secondary);
  padding: 32px 20px;
  text-align: center;
  margin: 0 20px;
  border-radius: 16px;
}

.membership-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.5px;
  margin-bottom: 8px;
}

.membership-subtitle {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 20px;
  line-height: 1.5;
}

/* ========== FOOTER ========== */
.footer {
  background: var(--bg);
  padding: 40px 20px 100px;
  border-top: 1px solid var(--border-light);
}

.footer-links {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 24px;
  margin-bottom: 32px;
}

.footer-links a {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--text-secondary);
  text-decoration: none;
  padding: 6px 0;
  transition: color 0.2s;
}

.footer-links a:hover {
  color: var(--text);
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 20px;
  border-top: 1px solid var(--border-light);
}

.footer-copy {
  font-family: var(--font-body);
  font-size: 11px;
  color: var(--text-muted);
}

.footer-social {
  display: flex;
  gap: 16px;
}

.footer-social a {
  color: var(--text-secondary);
  transition: color 0.2s;
}

.footer-social a:hover {
  color: var(--text);
}

.footer-social svg {
  width: 20px;
  height: 20px;
  fill: currentColor;
}

/* ========== PRODUCT DETAIL (VINTED STYLE) ========== */
.product-detail {
  min-height: 100dvh;
  padding-bottom: 120px;
  background: var(--bg);
}

/* Image Gallery */
.gallery-container {
  position: relative;
  width: 100%;
  height: 55vh;
  background: var(--bg-secondary);
  overflow: hidden;
}

.gallery-scroll {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  width: 100%;
  height: 100%;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.gallery-scroll::-webkit-scrollbar { display: none; }

.gallery-image {
  flex: 0 0 100%;
  scroll-snap-align: start;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg-secondary);
}

.gallery-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.gallery-dots {
  position: absolute;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 6px;
  z-index: 10;
}

.gallery-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.5);
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  padding: 0;
}

.gallery-dot.active {
  background: var(--accent-orange);
  width: 20px;
  border-radius: 4px;
}

/* Gallery Header (overlay) */
.gallery-header {
  position: absolute;
  top: 12px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 16px;
  z-index: 20;
}

.gallery-header-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  backdrop-filter: blur(10px);
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
  transition: all 0.2s;
}

.gallery-header-btn:active {
  transform: scale(0.92);
  background: rgba(255,255,255,1);
}

.gallery-header-btn svg {
  width: 20px;
  height: 20px;
  stroke: var(--text);
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Product Info */
.product-info {
  padding: 20px;
}

.product-info-price {
  font-family: var(--font-body);
  font-size: 28px;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.product-info-price .old {
  font-size: 18px;
  font-weight: 400;
  text-decoration: line-through;
  color: var(--text-muted);
}

.product-info-name {
  font-family: var(--font-body);
  font-size: 22px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 6px;
  line-height: 1.2;
}

.product-info-meta {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--text-secondary);
  margin-bottom: 12px;
}

.product-info-condition {
  display: inline-block;
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 4px;
  border: 1px solid var(--accent-green);
  color: var(--accent-green);
  background: rgba(0,125,72,0.05);
}

/* Action Buttons */
.product-actions {
  display: flex;
  gap: 12px;
  padding: 0 20px 16px;
}

.product-actions .btn {
  flex: 1;
}

/* Seller Card */
.seller-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-top: 0.5px solid var(--border);
  cursor: pointer;
  transition: background 0.2s;
}

.seller-card:active {
  background: var(--bg-secondary);
}

.seller-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  color: var(--text);
  flex-shrink: 0;
}

.seller-info {
  flex: 1;
}

.seller-name {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 2px;
}

.seller-rating {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  gap: 4px;
}

.seller-rating svg {
  width: 14px;
  height: 14px;
  fill: #FFB800;
  stroke: none;
}

.seller-chevron {
  color: var(--text-muted);
}

/* Description */
.description-section {
  padding: 16px 20px;
  border-top: 0.5px solid var(--border);
}

.section-detail-title {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text);
  margin-bottom: 12px;
}

.description-text {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* Details Grid */
.details-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.detail-item-label {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--text-secondary);
  margin-bottom: 2px;
}

.detail-item-value {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
}

/* Similar Products in Detail */
.similar-section {
  padding: 16px 0;
  border-top: 0.5px solid var(--border);
}

.similar-section .section-title-inline {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
  padding: 0 20px;
  margin-bottom: 12px;
}

/* ========== CART PAGE ========== */
.cart-page {
  min-height: 100dvh;
  padding: 52px 0 120px;
}

.cart-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 80px 20px;
  text-align: center;
}

.cart-empty svg {
  width: 80px;
  height: 80px;
  stroke: var(--text-muted);
  fill: none;
  stroke-width: 1;
  margin-bottom: 20px;
}

.cart-empty-title {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  margin-bottom: 8px;
}

.cart-empty-subtitle {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--text-secondary);
  margin-bottom: 24px;
}

.cart-item {
  display: flex;
  gap: 16px;
  padding: 16px 20px;
  border-bottom: 0.5px solid var(--border-light);
}

.cart-item-image {
  width: 80px;
  height: 80px;
  background: var(--bg-secondary);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  overflow: hidden;
}

.cart-item-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cart-item-details {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.cart-item-name {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  margin-bottom: 2px;
}

.cart-item-variant {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--text-secondary);
}

.cart-item-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 8px;
}

.cart-item-qty {
  display: flex;
  align-items: center;
  gap: 0;
  border: 0.5px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
}

.cart-item-qty button {
  width: 32px;
  height: 32px;
  background: none;
  border: none;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 16px;
  cursor: pointer;
  transition: all 0.15s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.cart-item-qty button:active {
  background: var(--bg-secondary);
}

.cart-item-qty span {
  width: 32px;
  text-align: center;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
}

.cart-item-price {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.cart-item-remove {
  width: 28px;
  height: 28px;
  background: none;
  border: none;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  margin-left: 8px;
  border-radius: 50%;
  transition: all 0.15s;
}

.cart-item-remove:active {
  background: var(--bg-secondary);
  color: #ff3b30;
}

.cart-item-remove svg {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
}

.cart-footer {
  position: fixed;
  bottom: 88px;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 480px;
  padding: 16px 20px;
  border-top: 0.5px solid var(--border);
  background: var(--bg);
  z-index: 50;
}

.cart-subtotal {
  display: flex;
  justify-content: space-between;
  margin-bottom: 6px;
}

.cart-subtotal-label {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--text-secondary);
}

.cart-subtotal-value {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
}

.cart-total {
  display: flex;
  justify-content: space-between;
  margin-bottom: 16px;
  padding-top: 12px;
  border-top: 0.5px solid var(--border-light);
}

.cart-total-label {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 700;
}

.cart-total-value {
  font-family: var(--font-body);
  font-size: 18px;
  font-weight: 700;
}

/* ========== FAVORIS PAGE ========== */
.favoris-page {
  min-height: 100dvh;
  padding: 52px 0 120px;
}

/* ========== BOUTIQUE PAGE ========== */
.boutique-page {
  min-height: 100dvh;
  padding: 52px 0 120px;
}

.search-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  background: var(--bg-secondary);
  border-radius: 12px;
  padding: 10px 14px;
  margin: 8px 20px 16px;
}

.search-bar svg {
  width: 20px;
  height: 20px;
  stroke: var(--text-muted);
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}

.search-bar input {
  border: none;
  background: none;
  outline: none;
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--text);
  width: 100%;
}

.search-bar input::placeholder {
  color: var(--text-muted);
}

/* ========== TOAST ========== */
.toast {
  position: fixed;
  bottom: 90px;
  left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--text);
  color: #fff;
  padding: 12px 20px;
  border-radius: 30px;
  display: flex;
  align-items: center;
  gap: 10px;
  z-index: 3000;
  opacity: 0;
  transition: all 0.3s var(--transition-bounce);
  max-width: 90vw;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  box-shadow: 0 8px 32px rgba(0,0,0,0.15);
  pointer-events: none;
}

.toast.show {
  transform: translateX(-50%) translateY(0);
  opacity: 1;
}

.toast-icon {
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.toast-icon svg {
  width: 16px;
  height: 16px;
  stroke: #fff;
  fill: none;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ========== SCROLL REVEAL ========== */
.scroll-reveal {
  opacity: 0;
  transform: translateY(20px);
  transition: all 0.6s var(--transition);
}

.scroll-reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ========== HORIZONTAL SCROLL ========== */
.horizontal-scroll {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding: 0 20px 8px;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.horizontal-scroll::-webkit-scrollbar { display: none; }

/* ========== CONTENT PADDING BOTTOM ========== */
.content-padded {
  padding-bottom: 100px;
}

/* ========== HOME PAGE REFONTE ========== */

/* Root container — scrollable, plein écran */
.hp-root {
  min-height: 100%;
  /* clip (et non hidden) : clippe le débordement horizontal SANS créer de
     conteneur de défilement, sinon le position:sticky des cartes catégories
     ne s'accroche plus au vrai scroller (.page) et l'effet d'empilement casse */
  overflow-x: clip;
  background: #fff;
}

/* ── Top bar ── */
.hp-topbar {
  position: sticky;
  top: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px 12px;
  background: rgba(255,255,255,0.96);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 0.5px solid rgba(0,0,0,0.07);
}

.hp-logo {
  font-family: var(--font-display);
  font-size: 26px;
  font-weight: 900;
  letter-spacing: -1.5px;
  color: #111;
  line-height: 1;
}

.hp-logo span {
  color: #09BA7D;
}

.hp-logo-svg {
  width: 50px;
  height: auto;
  display: block;
}

.hp-logo-svg path {
  fill: #111;
}

.hp-logo-dot {
  fill: #09BA7D;
}

.hp-cart-btn {
  position: relative;
  width: 40px;
  height: 40px;
  background: #f5f5f5;
  border: none;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.18s, transform 0.15s;
}

.hp-cart-btn:active { transform: scale(0.9); }

.hp-cart-btn svg {
  width: 19px;
  height: 19px;
  stroke: #111;
  fill: none;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.hp-cart-count {
  position: absolute;
  top: 1px;
  right: 1px;
  background: #09BA7D;
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  min-width: 16px;
  height: 16px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
  line-height: 1;
}

/* ── Hero ── */
.hp-hero {
  position: relative;
  width: 100%;
  aspect-ratio: 3/4;
  overflow: hidden;
  background: #f0ede8;
}

.hp-hero-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
  display: block;
  user-select: none;
}

/* léger éclaircissement bas pour la lisibilité du texte sombre */
.hp-hero::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 52%, rgba(255,255,255,0.6) 100%);
  pointer-events: none;
}

.hp-hero-label {
  position: absolute;
  bottom: 72px;
  left: 20px;
  z-index: 2;
}

.hp-hero-season {
  display: block;
  font-family: var(--font-body);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: rgba(0,0,0,0.45);
  margin-bottom: 6px;
}

.hp-hero-title {
  font-family: var(--font-display);
  font-size: clamp(34px, 10vw, 46px);
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -2px;
  color: #111;
}

.hp-hero-cta {
  position: absolute;
  bottom: 20px;
  right: 20px;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #111;
  color: #fff;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 600;
  padding: 12px 20px;
  border: none;
  border-radius: 30px;
  cursor: pointer;
  transition: background 0.2s, transform 0.15s;
  white-space: nowrap;
}

.hp-hero-cta:active {
  background: #333;
  transform: scale(0.96);
}

.hp-hero-cta svg {
  width: 15px;
  height: 15px;
  stroke: #fff;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}

/* ── Products horizontal scroll ── */
.hp-products-section {
  padding: 28px 0 0;
}

.hp-products-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 20px 14px;
}

.hp-products-label {
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: #999;
}

.hp-see-all {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 600;
  color: #111;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  transition: opacity 0.15s;
}

.hp-see-all:active { opacity: 0.5; }

.hp-products-scroll {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding: 0 20px 4px;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -ms-overflow-style: none;
  -webkit-overflow-scrolling: touch;
}

.hp-products-scroll::-webkit-scrollbar { display: none; }

.hp-product-card {
  flex: 0 0 148px;
  scroll-snap-align: start;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-align: left;
  transition: transform 0.18s;
}

.hp-product-card:active { transform: scale(0.96); }

.hp-product-img {
  position: relative;
  width: 148px;
  height: 180px;
  border-radius: 12px;
  overflow: hidden;
  background: #f5f4f2;
  margin-bottom: 9px;
}

.hp-product-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.35s;
}

.hp-product-card:hover .hp-product-img img {
  transform: scale(1.04);
}

.hp-tag-sale,
.hp-tag-new {
  position: absolute;
  top: 8px;
  left: 8px;
  font-family: var(--font-body);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 7px;
  border-radius: 4px;
}

.hp-tag-sale {
  background: #111;
  color: #fff;
}

.hp-tag-new {
  background: #09BA7D;
  color: #fff;
}

.hp-product-info {
  padding: 0 2px;
}

.hp-product-name {
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 500;
  color: #111;
  line-height: 1.3;
  margin-bottom: 3px;
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.hp-product-price {
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 700;
  color: #111;
  display: flex;
  align-items: center;
  gap: 5px;
}

.hp-product-old {
  font-size: 11px;
  font-weight: 400;
  color: #bbb;
  text-decoration: line-through;
}

/* ═══════════════════════════════════════════════════════════
   ACCUEIL — embellissements (hero anim · ticker · drop · reveal)
   NB : ne touche PAS .hp-root ni .hp-cats-* — un transform sur un
   ancêtre des cartes catégories casserait leur position:sticky.
   ═══════════════════════════════════════════════════════════ */

/* ── Hero : Ken Burns ambiant + entrée en cascade ── */
.hp-hero-img {
  animation: hp-hero-zoom 14s ease-out forwards;
}
@keyframes hp-hero-zoom {
  from { transform: scale(1); }
  to   { transform: scale(1.05); }
}

.hp-hero-season {
  opacity: 0;
  animation: hp-rise 0.6s var(--transition) 0.1s forwards;
}

/* le titre monte derrière un masque */
.hp-hero-title-mask {
  display: block;
  overflow: hidden;
}
.hp-hero-title {
  transform: translateY(110%);
  animation: hp-rise-up 0.7s var(--transition) 0.22s forwards;
}
@keyframes hp-rise-up {
  from { transform: translateY(110%); }
  to   { transform: translateY(0); }
}

/* opacité seule pour ne pas écraser le scale(0.96) du :active */
.hp-hero-cta {
  opacity: 0;
  animation: hp-fade-in 0.6s ease 0.45s forwards;
}
@keyframes hp-fade-in {
  to { opacity: 1; }
}

@keyframes hp-rise {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Ticker signature ── */
.hp-ticker {
  overflow: hidden;
  background: #111;
  border-top: 0.5px solid rgba(255,255,255,0.08);
  border-bottom: 0.5px solid rgba(255,255,255,0.08);
}
.hp-ticker-track {
  display: flex;
  width: max-content;
  animation: hp-ticker-scroll 22s linear infinite;
}
.hp-ticker-group {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}
.hp-ticker-item {
  display: inline-flex;
  align-items: center;
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #fff;
  padding: 11px 0;
  white-space: nowrap;
}
.hp-ticker-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #09BA7D;
  margin: 0 18px;
  flex-shrink: 0;
}
@keyframes hp-ticker-scroll {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ── Drop de la semaine ── */
.hp-drop {
  padding: 40px 16px 0;
}
.hp-drop-card {
  position: relative;
  display: block;
  width: 100%;
  aspect-ratio: 4 / 5;
  border: none;
  border-radius: 24px;
  overflow: hidden;
  cursor: pointer;
  background: #111;
  box-shadow: 0 14px 44px rgba(0,0,0,0.16);
  transition: transform 0.2s var(--transition);
  -webkit-tap-highlight-color: transparent;
}
.hp-drop-card:active { transform: scale(0.985); }
.hp-drop-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.5s var(--transition);
}
.hp-drop-card:hover .hp-drop-img { transform: scale(1.05); }
.hp-drop-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0.10) 0%, rgba(0,0,0,0.12) 40%, rgba(0,0,0,0.72) 100%);
}
.hp-drop-eyebrow {
  position: absolute;
  top: 18px;
  left: 20px;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #09BA7D;
}
.hp-drop-body {
  position: absolute;
  left: 20px;
  right: 18px;
  bottom: 20px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
}
.hp-drop-text {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
.hp-drop-badge {
  font-family: var(--font-body);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.3px;
  color: #fff;
  background: rgba(255,255,255,0.18);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  padding: 4px 9px;
  border-radius: 100px;
  margin-bottom: 10px;
}
.hp-drop-name {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 900;
  color: #fff;
  letter-spacing: -1px;
  line-height: 1;
  margin-bottom: 8px;
  text-align: left;
}
.hp-drop-price {
  font-family: var(--font-body);
  font-size: 16px;
  font-weight: 700;
  color: #fff;
  display: flex;
  align-items: center;
  gap: 8px;
}
.hp-drop-old {
  font-size: 13px;
  font-weight: 400;
  color: rgba(255,255,255,0.6);
  text-decoration: line-through;
}
.hp-drop-arrow {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.hp-drop-arrow svg {
  width: 19px;
  height: 19px;
  stroke: #111;
  fill: none;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* ── Apparition au scroll (jamais sur les catégories) ── */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s var(--transition), transform 0.6s var(--transition);
}
.reveal-in {
  opacity: 1;
  transform: none;
}

/* ── Accessibilité : on neutralise tout si l'utilisateur réduit les animations ── */
@media (prefers-reduced-motion: reduce) {
  .hp-hero-img,
  .hp-hero-season,
  .hp-hero-title,
  .hp-hero-cta,
  .hp-ticker-track {
    animation: none !important;
  }
  .hp-hero-title { transform: none !important; }
  .hp-hero-season,
  .hp-hero-cta { opacity: 1 !important; }
  .reveal { opacity: 1 !important; transform: none !important; }
}

/* ═══════════════════════════════════════════════════════════
   ACCUEIL v2 — direction éditoriale inspirée de BASKET
   (palette drip conservée : blanc + vert #09BA7D ; titres Anton,
   mot accent Instrument Serif italique, doodles verts)
   ═══════════════════════════════════════════════════════════ */

/* ── Ticker : séparateur étoile verte ── */
.hp-ticker-star {
  color: #09BA7D;
  font-size: 11px;
  margin: 0 16px;
  line-height: 1;
  flex-shrink: 0;
}

/* ── Hero éditorial ── */
.hp2-hero {
  padding: 22px 20px 6px;
  opacity: 0;
  animation: hp-fade-in 0.5s ease 0.05s forwards;
}

.hp2-eyebrow {
  display: inline-block;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #999;
  margin-bottom: 12px;
}

.hp2-title {
  margin: 0 0 6px;
  line-height: 0.9;
}
.hp2-title-caps {
  display: block;
  font-family: 'Anton', var(--font-display), sans-serif;
  font-weight: 400; /* Anton est déjà ultra-gras */
  font-size: clamp(42px, 14.5vw, 66px);
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #111;
}
.hp2-title-serif {
  position: relative;
  display: inline-block;
  font-family: 'Instrument Serif', Georgia, serif;
  font-style: italic;
  font-weight: 400;
  font-size: clamp(46px, 16vw, 72px);
  line-height: 1.04;
  color: #111;
  margin-top: 4px;
}
.hp2-underline {
  position: absolute;
  left: -2%;
  bottom: -4px;
  width: 104%;
  height: 16px;
  overflow: visible;
}
.hp2-underline path {
  fill: none;
  stroke: #09BA7D;
  stroke-width: 7;
  stroke-linecap: round;
}

/* visuel : sneaker encadrée par une arche verte + carte prix flottante */
.hp2-hero-visual {
  position: relative;
  margin-top: 14px;
}
.hp2-arch {
  width: 100%;
  background: #09BA7D;
  border-radius: 150px 150px 26px 26px;
  padding: 16px 16px 0;
  overflow: hidden;
}
.hp2-hero-img {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  object-position: center 20%;
  border-radius: 138px 138px 12px 12px;
  user-select: none;
}
.hp2-price-card {
  position: absolute;
  left: -2px;
  bottom: 18px;
  display: flex;
  flex-direction: column;
  background: #111;
  border-radius: 16px;
  padding: 11px 18px;
  box-shadow: 0 12px 30px rgba(0,0,0,0.22);
}
.hp2-price-label {
  font-family: var(--font-body);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.6);
  margin-bottom: 2px;
}
.hp2-price-value {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  color: #fff;
}

/* sous-titre + ellipse dessinée à la main */
.hp2-hero-sub {
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.55;
  color: #666;
  margin: 22px 0 20px;
}
.hp2-circle {
  position: relative;
  display: inline-block;
  color: #111;
  font-weight: 600;
  white-space: nowrap;
}
.hp2-circle-svg {
  position: absolute;
  left: -9px;
  top: -7px;
  width: calc(100% + 18px);
  height: calc(100% + 15px);
  overflow: visible;
  pointer-events: none;
}
.hp2-circle-svg path {
  fill: none;
  stroke: #09BA7D;
  stroke-width: 2.4;
  stroke-linecap: round;
}

/* boutons pills */
.hp2-cta-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.hp2-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 600;
  padding: 14px 22px;
  border-radius: 100px;
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: transform 0.15s, background 0.2s, opacity 0.2s;
  -webkit-tap-highlight-color: transparent;
}
.hp2-btn:active { transform: scale(0.96); }
.hp2-btn svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
  flex-shrink: 0;
}
.hp2-btn-dark { background: #111; color: #fff; }
.hp2-btn-outline { background: transparent; color: #111; border-color: #111; }
.hp2-btn-green { background: #09BA7D; color: #fff; }

/* ── Drop : eyebrow en pill vert + watermark numéro ── */
.hp-drop-eyebrow {
  top: 16px;
  left: 16px;
  color: #111;
  background: #09BA7D;
  padding: 5px 11px;
  border-radius: 100px;
  font-size: 10px;
  letter-spacing: 0.5px;
}
.hp-drop-watermark {
  position: absolute;
  right: 16px;
  top: 2px;
  font-family: 'Anton', var(--font-display), sans-serif;
  font-size: 88px;
  line-height: 1;
  color: rgba(255,255,255,0.13);
  pointer-events: none;
}

/* ── Bloc final "drops" (noir) ── */
.hp2-band {
  margin: 46px 16px 0;
  padding: 38px 26px 40px;
  background: #111;
  border-radius: 28px;
  text-align: center;
}
.hp2-band-eyebrow {
  display: inline-block;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #09BA7D;
  margin-bottom: 14px;
}
.hp2-band-title {
  font-family: 'Anton', var(--font-display), sans-serif;
  font-weight: 400;
  font-size: clamp(34px, 11vw, 50px);
  line-height: 0.95;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 14px;
}
.hp2-band-serif {
  font-family: 'Instrument Serif', Georgia, serif;
  font-style: italic;
  font-weight: 400;
  text-transform: none;
  color: #09BA7D;
}
.hp2-band-sub {
  font-family: var(--font-body);
  font-size: 13px;
  line-height: 1.5;
  color: rgba(255,255,255,0.62);
  max-width: 280px;
  margin: 0 auto 22px;
}
.hp2-band .hp2-btn-green {
  width: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .hp2-hero { animation: none !important; opacity: 1 !important; }
}

/* ── Categories : sticky-stack parallax ── */
.hp-cats-section {
  padding: 44px 0 0;
}

.hp-cats-eyebrow {
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.2px;
  color: #999;
  padding: 0 20px;
  margin-bottom: 20px;
}

/* pas d'overflow ici sinon position:sticky est cassé */
.hp-cats-stack {
  position: relative;
  padding: 0 16px;
}

/* chaque card s'épingle puis la suivante glisse par-dessus (le top
   est défini inline avec un décalage croissant pour laisser un liseré) */
.hp-cat-card {
  position: sticky;
  display: block;
  width: 100%;
  height: 230px;
  border: none;
  border-radius: 24px;
  overflow: hidden;
  cursor: pointer;
  margin-bottom: 18px;
  background: #111;
  box-shadow: 0 14px 44px rgba(0,0,0,0.16);
  transition: transform 0.2s var(--transition);
  -webkit-tap-highlight-color: transparent;
}

.hp-cat-card:active { transform: scale(0.985); }
.hp-cat-card:last-child { margin-bottom: 0; }

.hp-cat-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.5s var(--transition);
}

.hp-cat-card:hover .hp-cat-img { transform: scale(1.05); }

.hp-cat-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(165deg, rgba(0,0,0,0.10) 0%, rgba(0,0,0,0.20) 45%, rgba(0,0,0,0.66) 100%);
}

.hp-cat-index {
  position: absolute;
  top: 18px;
  left: 22px;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  color: rgba(255,255,255,0.85);
}

.hp-cat-body {
  position: absolute;
  left: 22px;
  right: 20px;
  bottom: 20px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
}

.hp-cat-name {
  display: block;
  font-family: var(--font-display);
  font-size: 30px;
  font-weight: 900;
  color: #fff;
  letter-spacing: -1px;
  line-height: 1;
  margin-bottom: 6px;
}

.hp-cat-sub {
  display: block;
  font-family: var(--font-body);
  font-size: 12px;
  font-weight: 500;
  color: rgba(255,255,255,0.82);
  line-height: 1.3;
}

.hp-cat-arrow {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(255,255,255,0.95);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: transform 0.2s var(--transition);
}

.hp-cat-card:hover .hp-cat-arrow { transform: translateX(3px); }

.hp-cat-arrow svg {
  width: 18px;
  height: 18px;
  stroke: #111;
  fill: none;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* espace pour ne pas masquer la dernière card sous la bottom-nav */
.hp-bottom-space {
  height: 130px;
}

