import { useState, useCallback, createContext, useContext, useEffect } from 'react'
import { products } from './data'
import './App.css'

import BottomNav from './components/BottomNav'
import Toast from './components/Toast'
import HomePage from './pages/HomePage'
import FavorisPage from './pages/FavorisPage'
import BoutiquePage from './pages/BoutiquePage'
import PanierPage from './pages/PanierPage'
import ProductDetailPage from './pages/ProductDetailPage'

// Navigation context
const NavigateContext = createContext(() => {})
export const useNavigate = () => useContext(NavigateContext)

export default function App() {
  // State
  const [currentPage, setCurrentPage] = useState('home')
  const [activeTab, setActiveTab] = useState('home')
  const [selectedProduct, setSelectedProduct] = useState(null)
  const [cart, setCart] = useState([])
  const [wishlist, setWishlist] = useState(new Set())
  const [boutiqueCategory, setBoutiqueCategory] = useState('all')
  const [toast, setToast] = useState({ message: '', visible: false })
  const [animationClass, setAnimationClass] = useState('')

  // Show toast
  const showToast = useCallback((message) => {
    setToast({ message, visible: true })
    setTimeout(() => setToast({ message: '', visible: false }), 2500)
  }, [])

  // Tab navigation
  const navigateToTab = useCallback(
    (tab) => {
      if (tab === activeTab && currentPage === tab) return
      setActiveTab(tab)
      setCurrentPage(tab)
      setAnimationClass('page-enter')
      setTimeout(() => setAnimationClass(''), 350)
    },
    [activeTab, currentPage]
  )

  // Ouvre la boutique pré-filtrée sur une catégorie (depuis l'accueil)
  const openCategory = useCallback(
    (category) => {
      setBoutiqueCategory(category)
      navigateToTab('boutique')
    },
    [navigateToTab]
  )

  // Navigation par la barre du bas : l'onglet Boutique repart sur "tout"
  const handleBottomNav = useCallback(
    (tab) => {
      if (tab === 'boutique') setBoutiqueCategory('all')
      navigateToTab(tab)
    },
    [navigateToTab]
  )

  // Navigate function for back buttons
  const navigateFn = useCallback(
    (page) => {
      if (page) {
        navigateToTab(page)
      } else {
        // Go back to active tab
        setAnimationClass('page-home-enter')
        setCurrentPage(activeTab)
        setSelectedProduct(null)
        setTimeout(() => setAnimationClass(''), 350)
      }
    },
    [activeTab, navigateToTab]
  )

  // Open product detail
  const openProduct = useCallback((id) => {
    const product = products.find((p) => p.id === id)
    if (!product) return
    setSelectedProduct(product)
    setCurrentPage('product-detail')
    setAnimationClass('page-enter')
    setTimeout(() => setAnimationClass(''), 350)
  }, [])

  // Toggle wishlist
  const toggleWishlist = useCallback(
    (id) => {
      setWishlist((prev) => {
        const next = new Set(prev)
        if (next.has(id)) {
          next.delete(id)
          showToast('Retiré des favoris')
        } else {
          next.add(id)
          showToast('Ajouté aux favoris')
        }
        return next
      })
    },
    [showToast]
  )

  // Add to cart
  const addToCart = useCallback(
    (product, size, color) => {
      setCart((prev) => {
        const existing = prev.find(
          (item) => item.id === product.id && item.size === size && item.color === color
        )
        if (existing) {
          return prev.map((item) =>
            item.id === product.id && item.size === size && item.color === color
              ? { ...item, qty: item.qty + 1 }
              : item
          )
        }
        return [
          ...prev,
          { id: product.id, name: product.name, price: product.price, image: product.image, size, color, qty: 1 },
        ]
      })
      showToast(`${product.name} ajouté au panier`)
    },
    [showToast]
  )

  // Update cart quantity
  const updateQty = useCallback((index, delta) => {
    setCart((prev) => {
      const next = [...prev]
      next[index] = { ...next[index], qty: next[index].qty + delta }
      if (next[index].qty <= 0) next.splice(index, 1)
      return next
    })
  }, [])

  // Remove from cart
  const removeFromCart = useCallback(
    (index) => {
      setCart((prev) => prev.filter((_, i) => i !== index))
      showToast('Article retiré')
    },
    [showToast]
  )

  // Checkout
  const checkout = useCallback(() => {
    showToast('Commande validée !')
    setCart([])
    setCurrentPage('panier')
  }, [showToast])

  // Cart count for badge
  const cartCount = cart.reduce((sum, item) => sum + item.qty, 0)

  // Header scroll effect
  useEffect(() => {
    const handleScroll = () => {
      const headers = document.querySelectorAll('.header')
      headers.forEach((h) => {
        if (window.scrollY > 60) h.classList.add('header-scrolled')
        else h.classList.remove('header-scrolled')
      })
    }
    window.addEventListener('scroll', handleScroll, { passive: true })
    return () => window.removeEventListener('scroll', handleScroll)
  }, [])

  // Keyboard escape to go back
  useEffect(() => {
    const handleKey = (e) => {
      if (e.key === 'Escape' && currentPage === 'product-detail') navigateFn()
    }
    window.addEventListener('keydown', handleKey)
    return () => window.removeEventListener('keydown', handleKey)
  }, [currentPage, navigateFn])

  // Scroll to top on page change
  useEffect(() => {
    window.scrollTo(0, 0)
  }, [currentPage])

  // Render current page
  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return (
          <HomePage
            onOpenProduct={openProduct}
            onNavigate={navigateToTab}
            onOpenCategory={openCategory}
            cartCount={cartCount}
          />
        )
      case 'favoris':
        return (
          <FavorisPage
            wishlist={wishlist}
            onToggleWishlist={toggleWishlist}
            onOpenProduct={openProduct}
          />
        )
      case 'boutique':
        return (
          <BoutiquePage
            wishlist={wishlist}
            onToggleWishlist={toggleWishlist}
            onOpenProduct={openProduct}
            initialCategory={boutiqueCategory}
          />
        )
      case 'panier':
        return (
          <PanierPage
            cart={cart}
            onUpdateQty={updateQty}
            onRemove={removeFromCart}
            onCheckout={checkout}
          />
        )
      case 'product-detail':
        if (!selectedProduct) return null
        return (
          <ProductDetailPage
            product={selectedProduct}
            isWishlisted={wishlist.has(selectedProduct.id)}
            onToggleWishlist={toggleWishlist}
            onAddToCart={addToCart}
            onOpenProduct={openProduct}
            onShare={showToast}
            wishlist={wishlist}
          />
        )
      default:
        return null
    }
  }

  return (
    <NavigateContext.Provider value={navigateFn}>
      <div className="app-container">
        <div className={`page ${animationClass}`}>{renderPage()}</div>

        <BottomNav
          activeTab={activeTab}
          onNavigate={handleBottomNav}
          cartCount={cartCount}
        />

        <Toast message={toast.message} visible={toast.visible} />
      </div>
    </NavigateContext.Provider>
  )
}

const tabs = [
  {
    key: 'home',
    label: 'Accueil',
    icon: (active) => (
      <svg viewBox="0 0 24 24" style={{ strokeWidth: active ? 2 : 1.5 }}>
        <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z" />
