]

export default function BottomNav({ activeTab, onNavigate, cartCount }) {
  return (
    <nav className="bottom-nav">
      {tabs.map((tab) => (
        <button
          key={tab.key}
          className={`bottom-nav-item ${activeTab === tab.key ? 'active' : ''}`}
          onClick={() => onNavigate(tab.key)}
        >
          <div style={{ position: 'relative' }}>
            {tab.icon(activeTab === tab.key)}
            {tab.key === 'panier' && cartCount > 0 && (
              <span className="nav-cart-badge">{cartCount}</span>
            )}
          </div>
          <span>{tab.label}</span>
        </button>
      ))}
    </nav>
  )
}

export default function ProductCard({ product, isCarousel = false, isWishlisted, onToggleWishlist, onOpenProduct }) {
  return (
    <div
      className={`product-card ${isCarousel ? 'product-card-carousel' : ''}`}
      onClick={() => onOpenProduct(product.id)}
    >
      <div className="product-image-wrap">
        <img src={product.image} alt={product.name} loading="lazy" />
        {product.tag && (
          <div className={`product-tag ${product.tag}`}>
            {product.tag === 'new' ? 'Nouveau' : '-15%'}
          </div>
        )}
        <button
          className={`product-wishlist ${isWishlisted ? 'active' : ''}`}
          onClick={(e) => {
            e.stopPropagation()
            onToggleWishlist(product.id)
          }}
        >
          <svg viewBox="0 0 24 24">
            <path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z" />
