import { useState, useMemo } from 'react'
import { useNavigate } from '../App'
import { products } from '../data'
import ProductCard from '../components/ProductCard'

const PILLS = [
  { key: 'all',         label: 'Tout'        },
  { key: 'shoes',       label: 'Chaussures'  },
  { key: 'clothing',    label: 'Vêtements'   },
  { key: 'accessories', label: 'Accessoires' },
]

const PAGE_SIZE = 6

export default function BoutiquePage({ wishlist, onToggleWishlist, onOpenProduct, initialCategory = 'all' }) {
  const navigate = useNavigate()
  const [filter, setFilter]       = useState(initialCategory)
  const [search, setSearch]       = useState('')
  const [visible, setVisible]     = useState(PAGE_SIZE)

  /* ── filtered list ── */
  const filtered = useMemo(() => {
    return products.filter((p) => {
      const matchCat    = filter === 'all' || p.category === filter
      const matchSearch = search === '' ||
        p.name.toLowerCase().includes(search.toLowerCase()) ||
        p.sub.toLowerCase().includes(search.toLowerCase())
      return matchCat && matchSearch
    })
  }, [filter, search])

  /* reset "voir plus" quand filtre change */
  const handleFilter = (key) => {
    setFilter(key)
    setVisible(PAGE_SIZE)
  }

  const handleSearch = (e) => {
    setSearch(e.target.value)
    setVisible(PAGE_SIZE)
  }

  const displayed   = filtered.slice(0, visible)
  const hasMore     = visible < filtered.length
  const remaining   = filtered.length - visible

  return (
    <div className="boutique-page">

      {/* ── Sticky top bar ── */}
      <div className="boutique-topbar">
        <button className="boutique-back-btn" onClick={() => navigate('home')}>
          <svg viewBox="0 0 24 24"><polyline points="15 18 9 12 15 6" /></svg>
        </button>
        <div className="drip-logo-sm">drip<span>.</span></div>
        <div style={{ width: 36 }} />
      </div>

      {/* ── Searchbar ── */}
      <div className="boutique-search">
        <svg viewBox="0 0 24 24">
          <circle cx="11" cy="11" r="8" />
          <path d="M21 21l-4.35-4.35" />
        </svg>
        <input
          type="text"
          placeholder="Chercher vêtements, shorts..."
          value={search}
          onChange={handleSearch}
        />
        {search && (
          <button className="search-clear" onClick={() => { setSearch(''); setVisible(PAGE_SIZE) }}>
            <svg viewBox="0 0 24 24"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        )}
      </div>

      {/* ── Category pills ── */}
      <div className="boutique-pills">
        {PILLS.map((pill) => {
          const count = pill.key === 'all'
            ? products.length
            : products.filter(p => p.category === pill.key).length
          return (
            <button
              key={pill.key}
              className={`boutique-pill ${filter === pill.key ? 'active' : ''}`}
              onClick={() => handleFilter(pill.key)}
            >
              {pill.label}
              <span className="pill-count">{count}</span>
            </button>
          )
        })}
      </div>

      {/* ── Promo banner (masqué si recherche active) ── */}
      {!search && filter === 'all' && (
        <div className="boutique-banner">
          <div className="boutique-banner-bg">DRIP</div>
          <div className="boutique-banner-text">
            <h3>Nouveautés Été 2025</h3>
            <p>Shoes, tees &amp; shorts à prix nets</p>
          </div>
          <button
            className="boutique-banner-btn"
            onClick={() => handleFilter('clothing')}
          >
            Voir
          </button>
        </div>
      )}

      {/* ── Section header ── */}
      <div className="boutique-section-head">
        <h2>
          {filter === 'all' ? 'Tous les articles' : PILLS.find(p => p.key === filter)?.label}
          <span className="section-count">{filtered.length}</span>
        </h2>
        {hasMore && (
          <span className="section-total">{remaining} de plus</span>
        )}
      </div>

      {/* ── Grid ── */}
      {displayed.length > 0 ? (
        <div className="boutique-grid">
          {displayed.map((p) => (
            <ProductCard
              key={p.id}
              product={p}
              isWishlisted={wishlist.has(p.id)}
              onToggleWishlist={onToggleWishlist}
              onOpenProduct={onOpenProduct}
            />
          ))}
        </div>
      ) : (
        <div className="boutique-empty">
          <svg viewBox="0 0 24 24">
            <circle cx="11" cy="11" r="8"/>
            <path d="M21 21l-4.35-4.35"/>
          </svg>
          <p>Aucun résultat pour « {search} »</p>
          <button onClick={() => { setSearch(''); setFilter('all') }}>
            Réinitialiser
          </button>
        </div>
      )}

      {/* ── Voir plus ── */}
      {hasMore && (
        <button
          className="boutique-voir-plus"
          onClick={() => setVisible((v) => v + PAGE_SIZE)}
        >
          Voir plus · {remaining} article{remaining > 1 ? 's' : ''}
          <svg viewBox="0 0 24 24"><polyline points="6 9 12 15 18 9" /></svg>
        </button>
      )}

      <div style={{ height: 100 }} />
    </div>
  )
}

