import { useState, useRef } from 'react'
import { products, similarProducts } from '../data'
import { useNavigate } from '../App'
import ProductCard from '../components/ProductCard'

export default function ProductDetailPage({ product, isWishlisted, onToggleWishlist, onAddToCart, onOpenProduct, onShare, wishlist }) {
  const navigate = useNavigate()

  // Partage : feuille de partage native (mobile) sinon copie du lien
  const handleShare = async () => {
    const shareData = {
      title: product.name,
      text: `${product.name} — ${product.price.toFixed(2)} €`,
      url: window.location.href,
    }
    try {
      if (navigator.share) {
        await navigator.share(shareData)
      } else if (navigator.clipboard) {
        await navigator.clipboard.writeText(window.location.href)
        onShare?.('Lien copié dans le presse-papier')
      }
    } catch {
      /* partage annulé par l'utilisateur — rien à faire */
    }
  }
  const [selectedSize, setSelectedSize] = useState(
    product.category === 'accessories' ? 'Taille unique' : '42'
  )
  const [currentImg, setCurrentImg] = useState(0)
  const galleryRef = useRef(null)

  const sizes = product.category === 'accessories'
    ? ['Taille unique']
    : ['38', '39', '40', '41', '42', '43', '44', '45', '46']

  const galleryImages = [product.image, product.image, product.image]

  const similar = similarProducts
    .filter((id) => id !== product.id)
    .map((id) => products.find((p) => p.id === id))
    .filter(Boolean)

  const handleScroll = () => {
    if (!galleryRef.current) return
    const idx = Math.round(galleryRef.current.scrollLeft / galleryRef.current.clientWidth)
    setCurrentImg(idx)
  }

  return (
    <div className="product-detail">
      {/* Gallery */}
      <div className="gallery-container">
        <div className="gallery-scroll" ref={galleryRef} onScroll={handleScroll}>
          {galleryImages.map((img, i) => (
            <div className="gallery-image" key={i}>
              <img src={img} alt={`${product.name} ${i + 1}`} />
            </div>
          ))}
        </div>

        <div className="gallery-header">
          <button className="gallery-header-btn" onClick={() => navigate()}>
            <svg viewBox="0 0 24 24"><polyline points="15 18 9 12 15 6" /></svg>
          </button>
          <div style={{ display: 'flex', gap: 8 }}>
            <button className="gallery-header-btn" onClick={() => onToggleWishlist(product.id)}>
              <svg viewBox="0 0 24 24" style={{ fill: isWishlisted ? '#ff3b30' : 'none', stroke: isWishlisted ? '#ff3b30' : 'var(--text)' }}>
                <path d="M20.84 4.61a5.5 5.5 0 00-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 00-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 000-7.78z" />
              </svg>
            </button>
            <button className="gallery-header-btn" onClick={handleShare} aria-label="Partager">
              <svg viewBox="0 0 24 24">
                <circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/>
                <line x1="8.59" y1="13.51" x2="15.42" y2="17.49"/><line x1="15.41" y1="6.51" x2="8.59" y2="10.49"/>
              </svg>
            </button>
          </div>
        </div>

        <div className="gallery-dots">
          {galleryImages.map((_, i) => (
            <button
              key={i}
              className={`gallery-dot ${i === currentImg ? 'active' : ''}`}
              onClick={() => {
                if (galleryRef.current) {
                  galleryRef.current.scrollTo({ left: i * galleryRef.current.clientWidth, behavior: 'smooth' })
                }
              }}
            />
          ))}
        </div>
      </div>

      {/* Info */}
      <div className="product-info">
        <div className="product-info-price">
          {product.price.toFixed(2)} €
          {product.oldPrice && <span className="old">{product.oldPrice.toFixed(2)} €</span>}
        </div>
        <div className="product-info-name">{product.name}</div>
        <div className="product-info-meta">drip. · {product.sub}</div>
        <div className="product-info-condition">{product.condition}</div>
      </div>

      {/* Actions */}
      <div className="product-actions">
        <button className="btn btn-primary" onClick={() => onAddToCart(product, selectedSize, product.color)}>
          Ajouter au panier
        </button>
        <button className="btn btn-secondary" onClick={() => onAddToCart(product, selectedSize, product.color)}>
          Message
        </button>
      </div>

      {/* Tailles */}
      {product.category !== 'accessories' && (
        <div className="description-section">
          <div className="section-detail-title">Taille</div>
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
            {sizes.map((s) => (
              <button
                key={s}
                onClick={() => setSelectedSize(s)}
                style={{
                  minWidth: 52, height: 44,
                  border: selectedSize === s ? '1.5px solid #111' : '1.5px solid #e5e5e5',
                  borderRadius: 8,
                  background: selectedSize === s ? '#111' : 'transparent',
                  color: selectedSize === s ? '#fff' : '#111',
                  fontSize: 13, fontWeight: 500,
                  cursor: 'pointer', transition: 'all 0.15s', padding: '0 16px',
                }}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Vendeur */}
      <div className="seller-card">
        <div className="seller-avatar">TM</div>
        <div className="seller-info">
          <div className="seller-name">Thomas M.</div>
          <div className="seller-rating">
            <svg viewBox="0 0 24 24"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" /></svg>
            <span>4.9 · 128 avis · 42 articles</span>
          </div>
        </div>
        <svg className="seller-chevron" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="9 18 15 12 9 6" />
        </svg>
      </div>

      {/* Description */}
      <div className="description-section">
        <div className="section-detail-title">Description</div>
        <div className="description-text">{product.desc}</div>
      </div>

      {/* Détails */}
      <div className="description-section">
        <div className="section-detail-title">Détails</div>
        <div className="details-grid">
          <div><div className="detail-item-label">Marque</div><div className="detail-item-value">Nike</div></div>
          <div><div className="detail-item-label">Taille</div><div className="detail-item-value">{product.size}</div></div>
          <div><div className="detail-item-label">État</div><div className="detail-item-value">{product.condition}</div></div>
          <div><div className="detail-item-label">Couleur</div><div className="detail-item-value">{product.color}</div></div>
          <div><div className="detail-item-label">Emplacement</div><div className="detail-item-value">{product.location}</div></div>
        </div>
      </div>

      {/* Similaires */}
      {similar.length > 0 && (
        <div className="similar-section">
          <div className="section-title-inline">Articles similaires</div>
          <div className="product-carousel">
            {similar.map((p) => (
              <ProductCard
                key={p.id}
                product={p}
                isCarousel
                isWishlisted={wishlist.has(p.id)}
                onToggleWishlist={onToggleWishlist}
                onOpenProduct={onOpenProduct}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

